def check_difference(weights: list[float], k: int) -> tuple[float, float]:
    def coefficient(index: int) -> float:
        return sum(w/n**2 * (1-1/n**2)**index for n,w in enumerate(weights, 1))
    observed = coefficient(k) - coefficient(k+1)
    predicted = sum(w/n**4 * (1-1/n**2)**k for n,w in enumerate(weights, 1))
    return observed, predicted

if __name__ == "__main__":
    print(check_difference([1.0, -1.0, 0.5, 2.0], 6))

