from __future__ import annotations
from math import comb
from typing import Sequence

def moment_transform(weights: Sequence[float], max_k: int) -> list[float]:
    """Compute cutoff coefficients from moments and the binomial transform."""
    moments = [
        sum(weight / n ** (2 * j + 2) for n, weight in enumerate(weights, start=1))
        for j in range(max_k + 1)
    ]
    return [
        sum((-1.0) ** j * comb(k, j) * moments[j] for j in range(k + 1))
        for k in range(max_k + 1)
    ]

from __future__ import annotations

def divisors(n: int) -> list[int]:
    if n < 1:
        raise ValueError("n must be positive")
    return [d for d in range(1, n + 1) if n % d == 0]

def mobius(n: int) -> int:
    remaining, factors, p = n, 0, 2
    while p * p <= remaining:
        if remaining % p == 0:
            remaining //= p
            factors += 1
            if remaining % p == 0:
                return 0
        p += 1
    if remaining > 1:
        factors += 1
    return -1 if factors % 2 else 1

def sigma_power(n: int, s: int) -> int:
    return sum(d ** s for d in divisors(n))

def divisor_mobius_identity(n: int, s: int) -> tuple[int, int]:
    lhs = sum(mobius(a) * sigma_power(n // a, s) for a in divisors(n))
    return lhs, n ** s

